        FederalReserveTfpData: {
            /**
             * Variable
             * @description The variable name (e.g., 'd_y', 'd_tfp', 'd_tfp_util').
             */
            variable?: string;
            /**
             * Variable Title
             * @description Human-readable title for the variable.
             */
            variable_title?: string;
            /**
             * Full Sample Mean
             * @description Mean value over the full sample period.
             */
            full_sample_mean?: string;
            /**
             * Past 4 Quarters
             * @description Mean value over the past 4 quarters.
             */
            past_4_quarters?: string;
            /**
             * Past 8 Quarters
             * @description Mean value over the past 8 quarters.
             */
            past_8_quarters?: string;
            /**
             * Since 2019:4
             * @description Mean value since 2019:Q4.
             */
            since_2019?: string;
            /**
             * 2004:4-2019:4
             * @description Mean value for the period 2004:Q4 to 2019:Q4.
             */
            period_2004_2019?: string;
            /**
             * 1995:4-2004:4
             * @description Mean value for the period 1995:Q4 to 2004:Q4.
             */
            period_1995_2004?: string;
            /**
             * 1973:1-1995:4
             * @description Mean value for the period 1973:Q1 to 1995:Q4.
             */
            period_1973_1995?: string;
            /**
             * 1947:1-1973:1
             * @description Mean value for the period 1947:Q1 to 1973:Q1.
             */
            period_1947_1973?: string;
            /**
             * Date
             * @description The date of the data.
             */
            date?: string;
            /**
             * Output (Product Side)
             * @description Business output, expenditure (product) side. From NIPA tables, Gross Value Added: Total Business: Quantity Index.
             */
            d_y_prod?: string;
            /**
             * Output (Income Side)
             * @description Business output, measured from income side. Nominal business output is GDI less nominal non-business output. Real business income uses expenditure-side deflator.
             */
            d_y_inc?: string;
            /**
             * Output
             * @description Output. Average of d_y_prod and d_y_inc (weighted equally). If d_y_inc not yet available, equals d_y_prod.
             */
            d_y?: string;
            /**
             * Hours
             * @description Hours worked in the business sector. From BLS productivity and cost release.
             */
            d_hours?: string;
            /**
             * Labor Productivity
             * @description Business-sector labor productivity, defined as d_y - d_hours. Note: Labor productivity in the BLS productivity-and-cost release equals d_y_prod - d_hours.
             */
            d_lp?: string;
            /**
             * Capital Input
             * @description Capital input. Perpetual inventory stocks calculated from disaggregated quarterly NIPA investment data, then growth rates are weighted by estimated rental prices.
             */
            d_k?: string;
            /**
             * Labor Quality (BLS Interpolated)
             * @description Labor composition/quality from BLS. Pre-1979 is interpolated annual BLS MFP estimate of labor composition (interpolated using Denton (1971) relative to changes in hours).
             */
            d_lq_bls_interpolated?: string;
            /**
             * Labor Quality (Aaronson-Sullivan)
             * @description Labor composition/quality following Aaronson-Sullivan. 1979:Q1 - present follows Aaronson and Sullivan (2001), as extended by Bart Hobijn and Joyce Kwok (FRBSF).
             */
            d_lq_aaronson_sullivan?: string;
            /**
             * Labor Quality
             * @description Labor composition/quality actually used. Pre-1979 is d_lq_bls_interpolated, 1979:Q1 onward uses d_lq_aaronson_sullivan.
             */
            d_lq?: string;
            /**
             * Capital Share
             * @description Capital's share of income (ratio between 0 and 1). Based primarily on NIPA data for the corporate sector, assuming private noncorporate factor shares match corporate shares.
             */
            alpha?: string;
            /**
             * TFP
             * @description Business sector Total Factor Productivity. Calculated as d_y - alpha*d_k - (1-alpha)*(d_hours+d_lq), i.e., output growth less the contribution of capital and labor.
             */
            d_tfp?: string;
            /**
             * Utilization
             * @description Utilization adjustment for capital and labor. Uses Basu, Fernald, Fisher, and Kimball (2013) estimates applied to quarterly data.
             */
            d_util?: string;
            /**
             * Utilization-Adjusted TFP
             * @description Utilization-adjusted Total Factor Productivity. Calculated as d_tfp - d_util, adjusting for variations in factor utilization.
             */
            d_tfp_util?: string;
            /**
             * Relative Price
             * @description Relative price growth of 'consumption' to price of 'equipment'. Measures the relative price of non-equipment goods and services to price of equipment (with consumer durables classified as equipment).
             */
            relative_price?: string;
            /**
             * Investment Share
             * @description Equipment and consumer durables share of business output (ratio between 0 and 1). Represents the proportion of output devoted to equipment investment and consumer durables.
             */
            inv_share?: string;
            /**
             * TFP (Investment)
             * @description TFP in equipment and consumer durables sector. Calculated from d_tfp assuming that relative price growth reflects relative TFP growth.
             */
            d_tfp_i?: string;
            /**
             * TFP (Consumption)
             * @description TFP in non-equipment business output ('consumption' goods and services). Calculated from d_tfp assuming that relative price growth reflects relative TFP growth.
             */
            d_tfp_c?: string;
            /**
             * Utilization (Investment)
             * @description Utilization adjustment in producing investment goods. Uses estimates from Basu, Fernald, Fisher, and Kimball to calculate utilization for producing equipment and consumer durables.
             */
            d_u_invest?: string;
            /**
             * Utilization (Consumption)
             * @description Utilization adjustment in producing non-investment business output ('consumption'). Uses estimates from Basu, Fernald, Fisher, and Kimball to calculate utilization for producing non-investment goods and services.
             */
            d_u_consumption?: string;
            /**
             * Utilization-Adjusted TFP (Investment)
             * @description Utilization-adjusted TFP in producing equipment and consumer durables. Calculated as d_tfp_i - d_u_invest.
             */
            d_tfp_i_util?: string;
            /**
             * Utilization-Adjusted TFP (Consumption)
             * @description Utilization-adjusted TFP in producing non-equipment business output ('consumption'). Calculated as d_tfp_c - d_u_consumption.
             */
            d_tfp_c_util?: string;
        } & {
            [key: string]: unknown;
        };
